      "baseAnswer": "There was a time when I was basically dating my phone. It was the first thing I touched in the morning and the last thing I said goodnight to. And the worst part? It wasn’t even fun. It felt like eating digital junk food, and I wasn’t full. I just felt empty. Eventually, I knew I had to do something. So I reached out to my friend Sara—every time I saw her, she barely touched her phone, like she was living in another universe. I asked her how she did it. She just laughed and said, ‘Oh, I used to be exactly like you.’ Then she handed me this book called How to Break Up with Your Phone and said, ‘Trust me, it changed my life.’ The book didn’t just say ‘put your phone down’—it showed me exactly why I couldn’t, and what to do about it. It broke down the science of attention addiction and gave me doable tricks to make my phone less tempting. After reading it, I deleted several distracting apps and left my phone across the room at night. These simple changes made it much less tempting. After a month, I felt so much better. My mind was quieter, and I was more focused. I still use my phone, but now it feels more like a tool instead of something that controls me. The best part is that I finally feel like I'm living again, not just watching other people live through a screen.",
